const s=[{id:"state-emotion-decisions",title:"Lerner ve arkadaşları · 2015 · Duygu ve karar verme · ST01 dosyası",url:"https://doi.org/10.1146/annurev-psych-010213-115043",type:"research",finding:"Yaklaşık 35 yıllık araştırmayı ele alan anlatı derlemesine göre, bir olaydan kalan duygular başka bir konudaki kararı da etkileyebilir. Bu etki, duyguya ve karara bağlı olarak yararlı veya zararlı olabilir.",limitation:"Birleştirilmiş tahmin yok. Üç parçalı bir ruh hâli mekanizmasını, herkese uyan en iyi ruh hâlini veya bir dakikalık toparlanmayı doğrulamaz."},{id:"state-regulation-meta",title:"Webb, Miles ve Sheeran · 2012 · Duygu düzenleme yöntemleri · ST02 dosyası",url:"https://pubmed.ncbi.nlm.nih.gov/22582737/",type:"research",finding:"306 deneysel karşılaştırmada ortalama etki, düşünme biçimini değiştirmede d = 0,36; tepkiyi düzenlemede 0,16; dikkati yönlendirmede 0,00’dı. Alt kategoriler ve ölçülen duygusal sonuçlar farklıydı.",limitation:"Çoğunlukla deneysel olarak oluşturulan duygular incelendi. Tedavi gören gruplar değil. Duygunun ifadesi ve yaşanması farklıdır. Belirli soru kalıplarını veya her zaman en iyi olan yöntemi doğrulamaz."},{id:"state-acute-exercise",title:"Reed ve Ones · 2006 · Bir seferlik egzersiz ve enerji · ST03 dosyası",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 çalışma, 450 etki, 13.101 katılımcı: enerjik olumlu duygularda egzersizle ilişkili düzeltilmiş ortalama değişim 0,47’ydi. Kontrol koşulunun değişimi ayrı olarak -0,17 bildirildi.",limitation:"Ayrı bildirilen bu değişimler, rastgele kontrollü tedavi karşılaştırması değildir. Çoğunlukla sağlıklı gönüllüler vardı, yanıtlar değişkendi. Kanıtlanmış iki dakikalık süre veya depresyon tedavisi gösterilmedi."},{id:"state-exercise-mental-health",title:"Singh ve arkadaşları · 2023 · Fiziksel etkinlik ve sıkıntı · ST04 dosyası",url:"https://doi.org/10.1136/bjsports-2022-106195",type:"research",finding:"1.039 ayrı rastgele kontrollü deneyi ve 128.119’dan fazla katılımcıyı kapsayan 97 derleme, belirtilerde ortalama azalma buldu. Depresyon ve kaygı etkilerinin ortancaları -0,43 ve -0,42’ydi.",limitation:"77 derlemenin kalitesi çok düşüktü. Uzun programlar kısa hareketten farklıdır. Sıkıntıdaki -0,60, 508 katılımcılı altı deney içeren tek derlemeden geldi. Başka küçük deneyde istatistiksel olarak anlamlı sonuç bulunmadı."},{id:"state-facial-feedback",title:"Coles, Larsen ve Lench · 2019 · Yüz ifadesi geri bildirimi · ST05 dosyası",url:"https://doi.org/10.1037/bul0000194",type:"research",finding:"138 çalışma ve 286 etkide genel d = 0,20; %95 güven aralığı 0,14 ile 0,26’ydı. Duyguların yaşanması ve duygusal yargılar birleştirildi. Etkiler küçük ve değişkendi.",limitation:"Yayımlanmış sayı 138, 136 değil. Bazı yargı etkileri yayın yanlılığı işaretleri gösterdi. Gülümsemeyi güvenilir bir sıkıntı tedavisi olarak belirlemez."},{id:"state-cyclic-sighing",title:"Balban ve arkadaşları · 2023 · Kısa nefes uygulamaları · ST09 dosyası",url:"https://doi.org/10.1016/j.xcrm.2022.100895",type:"research",finding:"108 yetişkin rastgele gruplara ayrılıp 28 gün boyunca günde beş dakika uyguladı. Çoğu Stanford’daki bir lisans psikoloji dersinden alındı. Modelleme, olumlu duygularda nefes uygulamalarını destekledi.",limitation:"Keşif amaçlı deneyin kaydı sonradan yapıldı. Kaygıda üstünlük, iki nefeslik süre, kalıcılık veya tedavi etkisi göstermez."},{id:"state-affect-labeling",title:"Lieberman ve arkadaşları · 2007 · Duyguları adlandırma · ST11 dosyası",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"30 sağlıklı yetişkin, beyin görüntüleme sırasında yüzlerdeki duyguları adlandırdı. Duygu sözcüğü ile cinsiyete uygun isim koşulları, amigdalada ölçülen bir değerde farklıydı. Bildirilen d = 0,79’du.",limitation:"Öznel sıkıntıdan toparlanma sonucu değildir. Daha hafif sözcüklerin, kendi duygunu adlandırmanın, kalıcı belirti azalmasının veya bu çalışma sayfasının yararını göstermez."},{id:"state-gratitude-expressed",title:"Kirca, Malouff ve Meynadier · 2023 · İfade edilen şükran · ST13 dosyası",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"23 çalışma ve 25 rastgele atanmış örneklemde olumlu iyi oluş üzerindeki etki, nötr kontrol koşullarına göre g = 0,22’ydi. İyi oluş için kullanılan başka etkinliklere göre g = 0,12’ydi. Bu ikinci karşılaştırmanın güven aralığı sıfırı içeriyordu.",limitation:"Makalede katılımcı toplamları çelişiyor. Bu yüzden tam sayı öğretilmiyor. Sabah hazırlık paketini, gelecek sahnelerini canlandırmayı veya güvenilir alternatiflere üstünlüğü doğrulamaz."},{id:"state-positive-self-statements",title:"Wood ve arkadaşları · 2009 · Olumlu kişisel cümleler · ST12 dosyası",url:"https://doi.org/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"İlk üniversite örneklemi deneyleri, tekrarlanan olumlu cümlelere yanıtların öz saygıya göre farklı olabileceğini gösterdi. Bazı katılanlar için daha kötü yanıt da olasıydı.",limitation:"Sonraki tekrar denemeleri ruh hâli, o anki öz saygı veya etkiyi değiştiren koşullara dair bulguları yeniden elde etmedi. Evrensel yarar veya zarar gösterilmedi. Coşkulu telkin üstünlüğü kanıtı yok."},{id:"state-mental-contrasting",title:"Wang, Wang ve Gai · 2021 · Hedefe ulaşma · ST15 dosyası",url:"https://doi.org/10.3389/fpsyg.2021.565202",type:"research",finding:"21 makale, 24 bağımsız etki, 15.907 katılımcı: zihinsel karşılaştırmayla yanıt planlamada g = 0,336 bulundu. Yayın yanlılığına göre düzeltilmiş tahmin daha küçüktü: 0,242.",limitation:"Çalışmalar farklıydı, yayın yanlılığı olasıydı. Dickens canlandırmasını, utancı, katı mecburiyet dilini veya bir uygulama biçiminin nedensel olarak üstün olduğunu doğrulamaz."},{id:"state-self-compassion-motivation",title:"Breines ve Chen · 2012 · Kendini geliştirme isteği · ST16 dosyası",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Dört kısa deney, şefkatle gelişme isteğinin birlikte bulunabileceğini destekledi. Başarısız sınavdan sonra çalışma süresi ortalama 306,5 saniyeydi. Hatırlatma almayan koşulda 203,2 saniyeydi.",limitation:"İkinci sınav notlarında istatistiksel olarak anlamlı fark bulunmadı. Öz saygı karşılaştırması kesin sonuç vermedi. Kalıcı değişimi, gerçek düzeltmeyi veya Dickens yönteminin etkisini kanıtlamaz."},{id:"state-nhs-panic",title:"NHS · Panik bozukluğu · ST18 dosyası",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Tekrar eden beklenmedik panik, uzman değerlendirmesi gerektirir. Kabul görmüş tedavi seçenekleri arasında bilişsel davranışçı terapi ve ilaç bulunur.",limitation:"Rehberdir, koçluk etkisi araştırması değildir. ODA paniğe tanı koyamaz. Yeni göğüs ağrısını, bayılmayı veya açıklanamayan nefes güçlüğünü zararsız kaygı sayamaz. Uygun tıbbi veya acil yardım kullan."},{id:"state-affirmation-replication",title:"Flynn ve Bordieri · 2020 · Olumlama tekrar çalışmaları · ST20 dosyası",url:"https://doi.org/10.1016/j.jcbs.2020.03.003",type:"research",finding:"İki üniversite benzetim deneyinde, olumlamalar için önceki ruh hâli ve o anki öz saygı bulguları yeniden elde edilemedi. Kişinin genel öz saygısına göre etkinin değişmesi de doğrulanmadı.",limitation:"Bu sonuçlar eşdeğerliği kanıtlamaz veya her olumlama için kesin bir sonuca varmamızı sağlamaz. İki başarısız tekrar denemesi, önceki yararları ve öz saygı farklarını belirsiz bırakır."}],d=[{schemaVersion:2,revision:2,id:"state-1",courseId:"state",locale:"tr",title:"Bir tartışmanın öfkesini sonraki konuşmaya taşıma",goal:"Başka bir olaydan kalan duyguyu fark et. Sonra güvenli bir ortamda yararlı bir isteğini ilet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Önceki konuşmanın öfkesi hâlâ içinde mi? Sıradaki isteğini kendi koşullarına göre değerlendir.",reason:{id:"state-1-reason",label:"Önceki duygunun sürmesi, bu yeni konuşmada sana neye mal oluyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Evde isteğimi açıkça dile getirmek","İş ilişkimi bu gerginlikten korumak","Bir tartışmanın etkisini diğerine taşımamak"]},why:{id:"state-1-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-1-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir duygu, ona neden olmuş gibi görünen durumdan önce başlamış olabilir. Zor bir vardiyadan kalan öfke, evdeki tamir isteğini etkileyebilir. Araştırmalar, duyguların ilgisiz başka kararlara taşınabildiğini gösteriyor. Bu, duygunun yanlış olduğu anlamına gelmez. Hangi olaydan geldiğine bak. Şu anki kişi, önceki tartışmanın sorumlusu olmayabilir.","Bu kurs için tekrarlanan bir geçiş anı seç: bir arama, mesaj veya önem verdiğin işe başlamadan önce. Duyguyu ve nereden gelmiş olabileceğini adlandır. Önce sakinleşmeyi şart koşmadan yararlı bir adım at. Gerçek zarara işaret eden öfkeyi gözden kaçırma. Açık bir istek, korunmak veya destek almak, ruh hâlini değiştirmekten daha önemli olabilir."],example:{title:"Derya tamir için mesaj gönderiyor",text:"Saat 18.00. Derya gergin bir vardiyadan sonra eve öfkeli geliyor. Akan musluğun onarılması gerekiyor. İşteki tartışmaya ev sahibinin neden olmadığını fark ediyor. Mutfak masasına oturup açık bir tamir isteği gönderiyor. Gelen yanıtta fotoğraf isteniyor. İlettiği isteği kaydedip fotoğrafı gönderiyor. Öfkesi hâlâ sürüyor. Ev sahibiyle konuşmasını, işte olanlardan ayrı tutuyor."}},move:{invitation:"Seçtiğin geçiş anında yararlı bir isteğini ilet. Duyguyu fark et, sonra cümlenle isteğini ilet.",instructions:["Duygunun nerede başlamış olabileceğini söyle.","Güvenli bir ortamda açık bir isteğini dile getir."],prompts:[],suggestions:{action:["Tamir için tek bir açık istek gönder","Gereken bir ayrıntıyı öğrenmek için sor","Somut bir ihtiyaç için destek iste"],minimum:["İsteğimi anlatan tek bir cümle gönder","Belirli bir konu hakkında tek soru sor","Destek gereken tek bir ihtiyacımı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Sıradaki gerekli mesajımı göndermeden önce","Bir sonraki güvenli görüşmem başladığında"],place:["Mutfak masamın başında otururken","Güvenle kullanabildiğim mesajlaşma kanalında"],minutes:[2,1,5],fallback:["Güvenli bir yazılı mesaj kullan","Daha sonraki güvenli bir fırsatı seç"],observation:["İlettiğim istek ve gelen gerçek yanıt","İsteğimi gerçekten iletip iletmediğim"]},suggested:{action:"Tamir için tek bir açık istek gönder",minimum:"İsteğimi anlatan tek bir cümle gönder",minutes:2,cueHint:"Sıradaki gerekli mesajımı göndermeden önce",placeHint:"Mutfak masamın başında otururken",obstacleHint:"Önceki konuşma hâlâ aklımda.",fallbackHint:"Güvenli bir yazılı mesaj kullan",observationHint:"İlettiğim istek ve gelen gerçek yanıt"},stopRule:"Gerçek tehlike varsa ara ver. Korunmayı veya destek almayı seç.",accessibleAlternative:"Gözlerini açık tut. Oturmaya devam et. Odaya dikkatini ver ve her zamanki iletişim yöntemini kullan."},result:{question:"Seçtiğin isteği gerçekten ilettin mi?",observationPrompt:"Tam olarak ne istedin, ardından nasıl bir yanıt geldi?"},judgment:{primary:{id:"state-1-carryover-request",scenario:"Tamir randevusu istemek için iki dakika kalmış. Gergin bir vardiyadan çıkan Derya, akan musluğun bu hafta onarılmasını istiyor. Ev sahibi daha önce makul yanıtlar verdi.",question:"Bu isteği duruma uygun biçimde nasıl iletebilir?",bestOptionId:"name-and-request",options:[{id:"pause-then-request",text:"Düşüncelerini toparlamak için beş dakika ara versin. Sonra durumu anlatan isteğini, tamir tarihini soran bir cümleyle göndersin.",feedback:"Süresi belli bir ara, isteğini düzenlemene yardımcı olabilir. Ama burada randevu fırsatı kaçıyor. Mesajı şimdi göndermek mümkün. Derya öfkesi sürerken de gerçek durumu anlatıp tarih isteyebilir."},{id:"describe-without-date",text:"Sızıntıyı kısaca anlatan bir mesajı hemen göndersin. Sonraki adımın ne olacağını ev sahibinin önermesine izin versin.",feedback:"Bu seçim sorunu doğru anlatıyor, randevu fırsatına yetişiyor. Ama Derya’nın bu hafta tamir ihtiyacı varken zamanı belirsiz bırakıyor. Tarih sormak, kabul edilmesini şart koşmadan ihtiyacını görünür kılar."},{id:"name-and-request",text:"Önceki olaydan kalan öfkeyi fark etsin. Musluktaki sızıntıyı anlatsın. Tamirin yapılacağı bir tarihi açıkça sorsun.",feedback:"Bu seçim duyguyu, bu konuşmaya dair gördüklerinden ayırıyor. Derya gereken isteği iletiyor, gelen yanıtı kaydedebilir. Sakinleşmek veya karşı tarafla anlaşmak, tamamlanma şartı değil. İstek ile yanıt ayrı kalır."}]}},carry:{takeaway:"Duygu nereden geldi, ona bak. Sıradaki isteğini o konuşmanın gerçeklerine göre dile getir.",followUp:{questionId:"state-1-return",question:"Ruh hâlin aynı kalsa da önceki duyguyu fark etmek, ilettiğin isteği değiştirdi mi?",observationPrompt:"İsteğinde veya ruh hâlinde ne değişti? İkisinin de aynı kalması geçerli bir yanıt.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Duygular bir karardan diğerine taşınabilir",paragraphs:["Lerner ve arkadaşları, duygu ve karar verme üzerine yaklaşık 35 yıllık araştırmayı inceledi. Başka bir yerde başlayıp yeni bir yargıyı etkileyen duyguları anlatıyorlar. Duygular kararları zorlaştırabilir, yardımcı da olabilir. İşe yarayan soru şu: bu duygu, şimdiki durum hakkında bilgi mi veriyor, yoksa daha önce olan bir şeyi mi yansıtıyor? Nereden geldiğine bakmak, onu yok saymak değildir. [ST01: state-emotion-decisions]","Bu ayrım öfkeyi, üzüntüyü veya kaygıyı silmeni istemiyor. Tekrarlanan hakaret, karşılanmamış ihtiyaç ve yorucu vardiya farklı gerçeklerdir. Yanıtını seçmeden önce şu anki kanıtı belirt. Tamir gerekiyorsa tamir iste. Korunman gerekiyorsa korunmayı seç. Bu ders, kararı görünür kılmak için gündelik bir istek kullanıyor. Önceki duyguyu adlandırmanın onu değiştirdiğini, karşı tarafın iş birliğini garantilediğini veya güvenli olmayan ilişkiyi çözdüğünü göstermiyor. Kötü muameleyi başka bir olaydan kalan öfke diye açıklamak zorunda değilsin."]},{heading:"Duygu testi yerine aynı denemeyi sürdür",paragraphs:["Bu kursta tekrarlanan tek bir geçiş anını ve hayatında istediğin tek bir yönü koru. Sonraki dersler, ancak kayıtların bir sorun gösterdiğinde o soruna uygun bir araç sunar. Yedi ayrı görev biriktirmiyorsun. Anlamlı gözlem, o anda ne istediğin, neye başladığın, neyi değiştirdiğin veya durdurduğundur. Ruh hâlin aynı kalmış olabilir. Mesajın yanıtsız kalabilir. Yine de isteğini iletmiş olabilirsin.","Webb ve arkadaşları, duygu düzenleme yöntemlerinin 306 deneysel karşılaştırmasını birleştirdi. Yorumu değiştirmek ortalama yararlar gösterdi. Ama yöntemler ve ölçülen sonuçlar farklıydı. Bazı sonuçlar duygunun ifadesiyle, bazıları yaşanmasıyla ilgiliydi. Bir duyguyu gizlemek, geçtiğini göstermez. Bu laboratuvar karşılaştırmaları beden, dikkat ve dil üçlüsünü veya ODA’nın kısa alıştırmasını doğrulamıyor. [ST02: state-regulation-meta] Kaydını kısa ve somut tut. Sonra verdiğin yanıta ve koşullarına bakarak sıradaki denemeyi seç."]}],sourceIds:["state-emotion-decisions","state-regulation-meta"]}},{schemaVersion:2,revision:2,id:"state-2",courseId:"state",locale:"tr",title:"Hâlâ enerjin yok mu? Küçük işi yine de dene",goal:"Aynı geçiş anında rahat bir hazırlığı dene. Sonra işin yararlı küçük bir kısmını yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hareket ettin ama beklediğin enerji gelmedi. Sıradaki küçük işi yine de yapabilir misin?",reason:{id:"state-2-reason",label:"Hangi yararlı iş bekliyor? Ne zaman dinlenip toparlanmak sana daha iyi gelir?",kind:"text",maxLength:160,optional:!0,suggestions:["Gücümün yettiği yerden işe başlamak","Yapmam gereken işte ilerlemek","Dinlenip toparlanmaya da yer bırakmak"]},why:{id:"state-2-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-2-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir seferlik aerobik egzersiz, enerjik hissetmeyi ortalama olarak artırabilir. Bu sonuç, fiziksel etkinlik programlarının klinik belirtilere etkisinden farklıdır. İki araştırma türü de iki dakikayı ruh hâlini güvenilir biçimde değiştiren bir süre olarak belirlemez. Kısa hareketin ardından herkes aynı sonucu yaşamaz.","Aynı geçiş anını ve yararlı işi koru. Hareket gücüne uyuyorsa müziği ve duruşunu değiştirmeden tek bir rahat seçenek dene. Sonra uygunsa işin en küçük kısmını yap. Dinlenmek veya hareket gerektirmeyen bir başlama işareti daha iyi uyabilir. Hazırlığını ve yaptığın yararlı işi ayrı kaydet. Birini yapmak, diğerinin yapıldığını göstermez."],example:{title:"Mert ilk slayt cümlesini yazıyor",text:"Saat 09.00. Mert bir bilgilendirme sunumu hazırlamadan önce enerjisiz hissediyor. Kısa, rahat bir yürüyüş seçiyor. Müzik listesini açmıyor. Masasına dönünce enerjisi aynı. Yine de slayta işe yarayan tek bir cümle yazıyor. İki gerçeği de kaydediyor. Slaytta daha yapılacak iş var. Sıradaki denemede oturarak başlamayı seçiyor. Yürüyüşü ve yazdığı cümleyi ayrı değerlendiriyor."}},move:{invitation:"Aynı geçiş anında, yararı olacaksa tek bir rahat hazırlık dene. Sonra işinin en küçük kısmını yap.",instructions:["Tek bir araç seç veya her zamanki hareketsiz hazırlığını koru.","Gücün yettiği ölçüde işte yararlı tek bir adım at."],prompts:[],suggestions:{action:["İşim için kullanılabilir tek bir cümle yaz","İşimde küçük bir düzeltmeyi tamamla","Seçtiğim açık isteği karşı tarafa gönder"],minimum:["İşe yarayan tek bir cümle yaz","İşimdeki tek bir hatayı düzelt","İsteğimi anlatan tek bir cümle gönder"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İsteğe bağlı rahat bir hareketten sonra","İşime geçmek için zaten seçtiğim anda"],place:["Çalışma masamın başında otururken","Rahatça erişebildiğim çalışma yerinde"],minutes:[2,1,5],fallback:["Hareket etmeden oturarak başlamayı seç","Dinlen, başka bir uygun fırsat seç"],observation:["Yaptığım hazırlık ve ardından tamamladığım iş","Hareketin rahatsızlık verip vermediği"]},suggested:{action:"İşim için kullanılabilir tek bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",minutes:2,cueHint:"İsteğe bağlı rahat bir hareketten sonra",placeHint:"Çalışma masamın başında otururken",obstacleHint:"Hazırlıktan sonra da enerjim düşük kalıyor.",fallbackHint:"Hareket etmeden oturarak başlamayı seç",observationHint:"Yaptığım hazırlık ve ardından tamamladığım iş"},stopRule:"Hareket rahatsızlık veriyorsa dur. Gerektiğinde dinlenmeyi veya destek almayı seç.",accessibleAlternative:"Oturarak hareket et, gözlerin açıkken odaya dikkatini ver veya hareketsiz bir işaret seç. Gülümsemek şart değil."},result:{question:"İşin işe yarayan en küçük kısmını yaptın mı?",observationPrompt:"Gerçekte hangi hazırlığı yaptın, işte hangi adımı attın?"},judgment:{primary:{id:"state-2-unchanged-energy",scenario:"Rahat bir yürüyüşten sonra Mert’in enerjisi değişmedi. Rahatsızlık yok. Slayttaki bilgiler kontrol edildi. Tek bir cümle yazabilecek durumda. Üç dakikası kaldı.",question:"Hangi sonraki adım bu denemeyi işe yarar kılar?",bestOptionId:"task-and-record",options:[{id:"timed-seated-start",text:"Oturarak başlamaya hazırlanmak için iki dakika ayırsın. Sonra geriye kalan bir dakikada slayta tek bir cümle yazsın.",feedback:"Hareket rahatsızlık veriyorsa veya oturarak başlamak senin için daha erişilebilirse bu seçenek yararlı olabilir. Mert burada ikisini de bildirmiyor. Ek hazırlık, belirlenmiş bir engeli ele almadan kalan zamanın çoğunu tüketir."},{id:"task-and-record",text:"İşe yarayan cümleyi yazsın. Enerjisinin değişmediğini kaydetsin. Bir sonraki denemede başka rahat bir hazırlık yapmayı düşünsün.",feedback:"Beklenen duygu değişimi olmadan da iş yapılabilir. Mert hangi hazırlığı denediğini, başlayıp başlamadığını öğrenir. Sonra bunu değiştirebilir. Ruh hâlini zorla yükseltmek için çabasını artırmak zorunda değil."},{id:"check-and-draft",text:"Kontrol edilmiş slayt bilgisini bir iş arkadaşına doğrulatsın. Gelen yanıtı beklerken slayt için geçici bir taslak cümle yazsın.",feedback:"Geçici taslak ve ikinci kontrol, gerçek bilgi belirsizliğini giderebilir. Burada bilgiler zaten kontrol edilmiş. Tek bir kullanılabilir cümleyi şimdi yazıp kaydetmek mümkünken bu seçim başka birinin yanıtına bağlılık ekliyor."}]}},carry:{takeaway:"Hazırlığı dürüstçe dene. Yararlı işin sonucuna bakarken gerçekten ne yaptığını esas al.",followUp:{questionId:"state-2-return",question:"Hazırlık başlamana yardımcı mı oldu, rahatsızlık mı verdi, yoksa dinlenmen gerektiğini mi gösterdi?",observationPrompt:"Yardımı, rahatsızlığı, toparlanma ihtiyacını veya belirgin fark olmadığını, işin sonucundan ayrı anlat.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Kısa süreli enerji ile tedavi farklı sorulardır",paragraphs:["Reed ve Ones, 13.101 kişinin katıldığı 158 çalışmayı ve bir seferlik aerobik egzersizleri birleştirdi. Derleme, enerjik ve uyanık hissetmek gibi olumlu, etkin duygularda egzersizle ilişkili ortalama değişimi 0,47 olarak bildirdi. Kontrol koşulunun değişimi ayrı bildirildi. Bunlar, egzersiz ile kontrolü karşılaştıran rastgele kontrollü bir tedavi etkisinin 0,47 olduğunu göstermez. Kişisel yanıtlar ve çalışma yöntemleri farklıydı. [ST03: state-acute-exercise]","Bu sonuç iki dakikalık süreyi, herkes için güvenilir enerjiyi veya depresyon tedavisini kanıtlamaz. Daha uzun fiziksel etkinlik programlarının ayrı bir üst derlemesinde belirtilerde ortalama azalmalar bulundu. Altındaki birçok derlemenin kalitesi çok düşük olarak değerlendirildi. [ST04: state-exercise-mental-health] Senin kısa hazırlığın, isteğe bağlı kişisel bir deneme. Erişimine, sağlığına ve gücüne uysun. Kaydın yorgunluk veya rahatsızlık gösteriyorsa aracı değiştirmek, destek istemek veya toparlanmayı korumak, egzersizi uzatmaktan daha iyi katkı sağlayabilir."]},{heading:"İsteğe bağlı ekler zorunlu hâle gelmesin",paragraphs:["İşine başlamak için gülümsemen, geniş yer kaplayan bir duruş veya belirli bir şarkı gerekmez. Coles ve arkadaşları 138 çalışmayı ve 286 etkiyi inceledi. Duyguların yaşanması ile yargıları birleştiren genel yüz ifadesi geri bildirimi tahmini küçüktü: 0,20. Etkiler değişiyordu. Bazı yargılarda yayın yanlılığı işaretleri vardı. Bu, gülümsemenin sıkıntıya güvenilir bir yanıt olduğunu göstermez. [ST05: state-facial-feedback] Hazırlığında zorla gülümsemek şart olmamalı.","Sürdürdüğün bu denemede bir seferde tek hazırlığı değiştir. Hangi işi yapmak istediğin açık kalsın. Şarkı, duruş ve hareketi birlikte ekleyip hangisinin işe yaradığını tahmin etmek yerine diğer koşullarını her zamanki gibi tut. Kişisel bir gözlem, başka bir deneme seçmene yardımcı olabilir. Biyolojik mekanizmayı ayıramaz veya neden-sonuç belirleyemez. Sıradaki iş gücüne hâlâ uyuyorsa enerji artışı olmadan da en küçük kısmını yapabilirsin. Toparlanmak daha uygunsa daha iyi hissetmeyi zorlamak yerine o seçimi dürüstçe kaydet."]}],sourceIds:["state-acute-exercise","state-exercise-mental-health","state-facial-feedback"]}},{schemaVersion:2,revision:2,id:"state-3",courseId:"state",locale:"tr",title:"Çok mu gerginsin? Sakinleşmeyi kovalamadan ara ver",goal:"Rahat bir ara seç. Sonra mevcut yararlı davranışını veya uygun bir destek adımını yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir nefes alıştırması daha bekleyebilir. Hangi yanıtı vermeden önce durup seçim yapman gerekiyor?",reason:{id:"state-3-reason",label:"Ara vermek neyi destekler, neyi geciktirir?",kind:"text",maxLength:160,optional:!0,suggestions:["Yanıtımı düşünerek vermek","Durmam gerektiğini gösteren işarete uymak","İşe yarayan somut destek istemek"]},why:{id:"state-3-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-3-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Çok konuşulan iç çekme araştırmasında 28 gün boyunca günde beş dakika uygulandı. İki nefesin anında sakinleştiren bir düğme olup olmadığı sınanmadı. Nefesini zorlamadığın bir mola, isteğe bağlı hazırlıktır. Seçtiğin yolun gerektirdiği asıl davranışın kendisi değildir.","Aynı geçiş anına ve davranışına dön. Güvenli bir yerde otur. Normal nefesini koruyabilir, gözlerini açık tutup odayı fark edebilirsin. Rahatsa hafifçe nefes al, ardından küçük bir nefes daha al ve zorlamadan yavaşça ver. Baş dönmesi, karıncalanma, nefes darlığı veya rahatsızlıkta dur. Sonra uygun yanıtı, dinlenmeyi veya desteği seç. Yeni, şiddetli fiziksel belirtiler tıbbi değerlendirme gerektirir. Bunları stres diye açıklama."],example:{title:"Elif’in bekleyen e-posta yanıtı",text:"Öğle yemeğinden sonra Elif masasında, acil olmayan bir e-posta yüzünden gergin. Nefesine odaklanmak rahatsızlık veriyor. Gözlerini açık tutup pencere çerçevesine dikkat ediyor. Sonra gerçek durumu açıklığa kavuşturan tek bir cümle gönderiyor. Kaygısı sürüyor. Yanıt henüz gelmedi. Dikkatini çevresine verdiği molayı ve gönderdiği cümleyi kaydediyor. Bunu başarılı bir nefes alıştırması gibi göstermiyor."}},move:{invitation:"Aynı davranışından önce rahat bir ara seç. Normal nefes alıp dikkatini çevrene vermek de geçerli seçenekler.",instructions:["Otur. Araç kullanma, sudan ve düşme riski olan yerlerden uzak dur.","Aradan sonra uygunsa seçtiğin davranışın en küçük kısmını yap."],prompts:[],suggestions:{action:["Düşünerek seçtiğim tek yanıt cümlesini gönder","Gereken bir ayrıntıyı öğrenmek için sor","Tek bir ihtiyaç için destek iste"],minimum:["Gerçek durumu anlatan tek bir cümle gönder","Tek bir açık soru sor","Destek gereken tek bir ihtiyacımı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İsteğe bağlı rahat bir aradan sonra","Sıradaki acil olmayan yanıtımdan önce"],place:["Kendi masamda güvenle otururken","Güvenli, yalnız kalabildiğim bir koltukta"],minutes:[2,1,5],fallback:["Normal nefes al, dikkatini çevrende olup bitene ver","Dur, destek için bir adım seç"],observation:["Moladaki rahatlığım ve gerçekten verdiğim yanıt","Durma işaretine uyup uymadığım"]},suggested:{action:"Düşünerek seçtiğim tek yanıt cümlesini gönder",minimum:"Gerçek durumu anlatan tek bir cümle gönder",minutes:2,cueHint:"İsteğe bağlı rahat bir aradan sonra",placeHint:"Kendi masamda güvenle otururken",obstacleHint:"Nefesime odaklanmak rahatsızlık veriyor.",fallbackHint:"Normal nefes al, dikkatini çevrende olup bitene ver",observationHint:"Moladaki rahatlığım ve gerçekten verdiğim yanıt"},stopRule:"Baş dönmesi, karıncalanma, nefes darlığı veya rahatsızlıkta dur. Normal nefesine dön. Yeni, şiddetli göğüs ağrısı veya açıklanamayan nefes güçlüğü tıbbi değerlendirme gerektirir.",accessibleAlternative:"Gözlerini açık tut. Oturmaya devam et. Nötr bir nesneye bak. Nefesini değiştiren alıştırmayı atla."},result:{question:"Seçtiğin davranışı gerçekten yaptın mı?",observationPrompt:"Neyi rahat buldun, ardından gerçekte nasıl bir yanıt verdin?"},judgment:{primary:{id:"state-3-uncomfortable-pause",scenario:"Elif nefes denemesini durdurup otururken normal nefesine dönüyor. Sersemlik sürüyor ve daha önce yaşamadığı bir şey. Yanıtı acil değil. Yakındaki bir iş arkadaşı yardım edebilir.",question:"Şimdi hangi adım değişmeli?",bestOptionId:"stop-and-support",options:[{id:"stop-and-support",text:"Oturmayı ve normal nefesi sürdürsün. E-postayı ertelesin. Tıbbi görüş almak için iş arkadaşından yardım istesin.",feedback:"Uygun biçimde durdu. Belirti sürüyor ve daha önce yaşamadığı bir şey. Zamanında yardım, e-postadan veya başka bir araçtan önce gelir. Şiddetli belirti veya acil tehlike, acil yardım gerektirir."},{id:"stop-and-look-outward",text:"Oturarak normal nefesini sürdürsün. Dikkatini pencere çerçevesine versin. Sonra yanıt vermeden önce durumuna yeniden baksın.",feedback:"Dikkatini çevrene vermek, rahatsızlık veren nefese odaklanmanın yerini alabilir. Burada yeni belirti, durduktan sonra da sürüyor. Bir nesneye odaklanmak, yardım istemeyi ve uygun tıbbi görüş almayı geciktirmemeli."},{id:"stop-and-defer",text:"Oturarak normal nefesini sürdürsün. E-postayı yarına bıraksın. Daha sonra sersemliğinin geçip geçmediğini kontrol ederek nasıl hissedeceğine baksın.",feedback:"Acil olmayan mesajı ertelemek, sağlıkla ilgilenmeye zaman bırakır. Ama mesajı geciktirmek, süren ve tanımadığı belirtiyi ele almıyor. Değerlendirmeyi de ertelemek yerine şimdi uygun yardım iste. İki işi birbirine karıştırma."}]}},carry:{takeaway:"Güvenle durmak yararlı bilgi verir. Düşünerek yanıt vermek için sakinleşmiş olman şart değil.",followUp:{questionId:"state-3-return",question:"Ara vermek rahat mıydı? Davranışını destekledi mi, yoksa başka bir araç mı gerekiyor?",observationPrompt:"Rahatlığı, durma veya destek ihtiyacını ve sonraki yanıtını ayrı ayrı anlat.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"İç çekme deneyinde gerçekte ne sınandı?",paragraphs:["Balban ve arkadaşları 108 yetişkini rastgele kısa nefes uygulamalarına veya farkındalık çalışmasına ayırdı. Katılanlar 28 gün boyunca günde beş dakika uygulama yaptı. Çoğu, Stanford’daki bir lisans psikoloji dersinden alındı. Çalışma keşif amaçlıydı ve araştırma kaydı sonradan yapıldı. Modelleme, olumlu duygularda nefes uygulamalarını destekledi. Kaygıda üstünlük veya iki nefesten güvenilir sonuç göstermedi. [ST09: state-cyclic-sighing]","Araştırılan döngüsel iç çekme, otururken veya uzanırken yavaş nefes almak, daha kısa ikinci bir nefes almak ve yavaş vermekti. Bu ders, rahat ve isteğe bağlı bir denemeyle normal nefes alternatifleri sunuyor. Güvenlik ve erişim seçimleri ODA uyarlamalarıdır. Akciğerlerini zorlayarak doldurup boşaltma. Nefesini tutma veya etkiyi zorlamak için hızlanma. Kaydında hazırlığı, durdurduğun denemeyi ve asıl yanıtını ayırabilirsin. Biri diğerlerinin yerine geçmez. Bir yanıt gönderdiğinde bunu nefes denemesinden ayrı bir davranış olarak kaydet."]},{heading:"Nefes alıştırması bir belirtiye tanı koymaz",paragraphs:["Nefes alıştırması fiziksel belirtinin nedenini söyleyemez. NHS rehberi, tekrar eden beklenmedik panik için uzman değerlendirmesi önerir ve kabul görmüş tedavi seçeneklerini anlatır. Kursun sınırı açık: ODA eğitimdir, tanı veya tedavi değildir. Tanımadığın göğüs ağrısını, bayılmayı veya açıklanamayan nefes güçlüğünü zararsız kaygı sayma. Yeni, şiddetli belirtiler tıbbi değerlendirme gerektirir. Acil tehlike, acil yardım gerektirir. [ST18: state-nhs-panic]","Nefesini değiştirmeden de somut bir yanıt seçebilirsin. Gözlerin açık kalsın. Nötr bir nesneyi fark et, otur veya destek iste. Ara vermek seni daha rahatsız ediyorsa bırak. Dayanmayı ilerleme sayma. Ortam güvenliyse ve yanıtı verebilecek durumdaysan yararlı bir isteği iletmeden önce sakinleşmek zorunda değilsin. Dinlenmek, korunmak veya birinden yardım almak uygunsa isteği sürdürmek zorunda da değilsin. O andaki koşullara göre seçim yap. Ders, asıl isteği her durumda göndermeni şart koşmuyor."]}],sourceIds:["state-cyclic-sighing","state-nhs-panic"]}},{schemaVersion:2,revision:2,id:"state-4",courseId:"state",locale:"tr",title:"Yine başa mı sardın? İşe yarayan soruyu sor",goal:"Tekrarlanan durumunla ilgili tek bir soruyu, yararlı bir davranışa veya uygun destek isteğine dönüştür.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir kez daha “Neden?” sormak yeni bilgi getirmiyorsa hangi yanıt önündeki on dakikayı değiştirir?",reason:{id:"state-4-reason",label:"Bu durumu tekrar tekrar düşünürken hangi işi sonraya bırakıyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek bir sorunu açıklığa kavuşturmak","Öğrendiğim bilgiyi işimde kullanmak","Yararlı bir isteği artık ertelememek"]},why:{id:"state-4-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-4-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir soru, yanıtı seçimini değiştirdiğinde işe yarar. “Neden?” sormak bir nedeni, beceri eksiğini veya düzeltmenin kimin sorumluluğu olduğunu gösterebilir. Kendiliğinden zararlı değildir. Ama yeni bilgi olmadan aynı durumu yeniden düşünmek, sıradaki adımını değiştirmeyebilir. Araştırmakla düşünceyi tekrar edip durmayı ayır. Birinden bilgi alabilir, diğerinde aynı noktada kalabilirsin.","Seçtiğin geçiş anında neyi netleştirmek, değiştirmek veya hangi desteği almak gerektiğini sor. Yanıtında yapacağın iş olsun: gönder, düzelt, sor, dinlen. Araştırmalar bu cümleleri değil, geniş yöntemleri karşılaştırıyor. Bunu pratik bir yardımcı olarak gör. Mümkünse yanıtın gerektirdiğini yap. Sonra cesaret verici sözleri değil, ne yaptığını kaydet. Yanıt, gerçek durumundaki seçime katkı sağlasın."],example:{title:"Ömer bütçeyi onaylayacak kişiye ulaşmamış",text:"Saat 14.00. Ömer masasında ilerlemeyen proje isteğine bakıyor. “Neden?” diye sormak, kişisel başarısızlık yerine eksik bütçe onayını gösteriyor. Proje notlarında belirtilen kişiyi bulup tek bir açıklama isteği gönderiyor. O öğleden sonra yanıt gelmiyor. Daha fazla cesaret verici soru yazmak yerine sorduğu soruyu, mesajı ve hâlâ bekleyen onayı kaydediyor. Henüz onay almış değil."}},move:{invitation:"Aynı durum hakkında yararlı tek bir soru sor. Yanıtın gösterdiği, uygun en küçük davranışı yap.",instructions:["Gerektiğinde araştırmayı sürdür ve kimin sorumlu olduğunu açık tut.","Yanıta göre bir istek ilet veya bir düzeltme yap."],prompts:[],suggestions:{action:["Gereken bir ayrıntı için açıklama iste","İşimde belirlediğim tek bir sorunu düzelt","Eksik olan tek bir kaynağı iste"],minimum:["Açıklama isteyen tek bir cümle gönder","İşimdeki tek bir hatayı düzelt","Eksik olan tek bir kaynağı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İşe yarayan sorumu yanıtladıktan sonra","İşime geçmek için zaten seçtiğim anda"],place:["Kendi masamın veya telefonumun başında","Güvenle kullanabildiğim mesajlaşma kanalında"],minutes:[2,1,5],fallback:["Yanıtı bulmak için yardım iste","Yanıt vermek için uygun bir fırsat planla"],observation:["Bulduğum yanıt ve gerçekten attığım adım","Henüz çözüme ulaşmamış olan kısım"]},suggested:{action:"Gereken bir ayrıntı için açıklama iste",minimum:"Açıklama isteyen tek bir cümle gönder",minutes:2,cueHint:"İşe yarayan sorumu yanıtladıktan sonra",placeHint:"Kendi masamın veya telefonumun başında",obstacleHint:"Sıradaki adımı atmadan tekrar tekrar inceliyorum.",fallbackHint:"Yanıtı bulmak için yardım iste",observationHint:"Bulduğum yanıt ve gerçekten attığım adım"},stopRule:"Gereken korunmanın veya desteğin yerine bir düşünme alıştırması daha koyma.",accessibleAlternative:"İçinden veya her zamanki iletişim yönteminle yanıtla. Destek istemek de yararlı davranışın olabilir."},result:{question:"Yararlı yanıtına göre gerçekten adım attın mı?",observationPrompt:"Soru neyi gösterdi, hemen ardından gerçekte ne yaptın?"},judgment:{primary:{id:"state-4-question-to-action",scenario:"Ömer, isteğinde gereken bütçe alanlarının dolu olduğunu doğruluyor. Ama istek onaylayacak kişiye hiç ulaşmamış. Listede belirtilen kişi şu an açıklama mesajlarını alabiliyor.",question:"Yararlı sorunun ardından hangi adım gelmeli?",bestOptionId:"contact-approver",options:[{id:"check-budget-field",text:"Onaylayacak kişiye eksiksiz bir istek ulaşsın diye açıklama mesajını göndermeden önce doldurduğu bütçe alanlarını bir kez daha kontrol etsin.",feedback:"Gerekli alanları kontrol etmek, boşa gidecek mesajı önleyebilir. Ömer bunları zaten doğruladı. Eksik adım, iletmek. Kontrolü tekrarlamak, bilinen bu eksiği gidermeden hazırlık ekliyor. Mesaj henüz gereken kişiye ulaşmıyor."},{id:"break-then-contact",text:"Beş dakika ara versin. Sonra can sıkıntısını mesaja yansıtmadan, gerçek durumu anlatan açıklama isteğini göndersin.",feedback:"Bu seçimin bir bitişi var. Ara gerektiğinde yardımcı olabilir. Burada böyle bir ihtiyaç görülmedi. Gerçek durumu anlatan açıklama isteği hazır ve eksik onayı doğrudan ele alıyor."},{id:"contact-approver",text:"Listedeki onaylayacak kişiye gerçek durumu anlatan bir açıklama isteği göndersin. Sonra gelen yanıtı veya yanıt gelmediğini kaydetsin.",feedback:"Bu seçim belirlenen nedeni, kişinin yapabileceği bir davranışa dönüştürüyor. Yanıt gelmeyebilir. Onay başkasına bağlı kalır. Ömer yine de yararlı isteği iletip iletmediğini kaydedebilir. Başkasının kararını kendi davranışıyla karıştırmaz."}]}},carry:{takeaway:"Bir yanıt, bundan sonra yapacağın yararlı adımı değiştirdiğinde ona ayırdığın zamana değer.",followUp:{questionId:"state-4-return",question:"Sorduğun soru bir şeyi netleştirip ne yapacağını değiştirdi mi, yoksa yalnızca cesaret verici mi geldi?",observationPrompt:"Neyin netleştiğini, neyin değiştiğini belirt. Yeni bilgi veya değişiklik olmaması da geçerli.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Dikkat bulguları belirli bir soru listesini doğrulamaz",paragraphs:["Webb ve arkadaşları 306 deneysel karşılaştırmayı birleştirdi. Düşünme biçimini değiştiren geniş yöntemlerin duygusal sonuçlardaki ortalama etkisi 0,36’ydı. Dikkati yönlendirmenin genel ortalaması sıfıra yakındı. Ama alt türleri farklıydı. Bu kategoriler farklı yönergeleri ve deneysel olarak oluşturulan kısa duyguları kapsıyordu. Adı olan bir sabah soru listesinin ruh hâlini iyileştirdiğini kanıtlamıyorlar. “Neden?” sormanın veya soruna odaklanmanın genel olarak zararlı olduğunu da göstermiyorlar. [ST02: state-regulation-meta]","Bir sorunun ne işe yaradığını anlamak için bu ayrımı kullan. Araştırmak gerçekleri belirleyebilir. Sorumluluğa bakmak, kimin ilgilenmesi gerektiğini gösterebilir. Planlamak eksik kaynağı ortaya koyabilir. Her biri zaman ayırmaya değer olabilir. Yanıtın yapabileceğin bir davranış gösteriyorsa onu seç. Dışarıdaki bir kısıtı gösteriyorsa o kısıtı tutum sorunu diye anlatma. ODA’nın soru ve davranışı birleştirmesi bir uyarlamadır. Doğrulanmış süresi veya duygusal sonuç sözü olan sınanmış bir uygulama değildir."]},{heading:"Yanıtı sürdürdüğün denemeyle bağlantılı tut",paragraphs:["Denemenin zaten bir yönü, geçiş anı ve yararlı davranışı var. Bunlar görünür kalsın. Soru, yeni bir günlük ritüel olmak yerine davranışını geliştirsin. Örneğin açıklama isteği, eksik onayı ele alabilir. İşteki bir adımla belirlediğin bir hatayı düzeltebilirsin. Korunma adımı, zararlı iletişime yanıt verebilir. Sadece sıradaki seçimin için gerekli bilgiyi sor. Daha fazla soru yazmak tek başına daha fazla ilerleme değildir.","Duygular bir yanıtı nasıl yorumladığını etkileyebilir. Başka bir olaydan taşınmış da olabilir. Lerner ve arkadaşları, duygunun kararlara yararlı ve zararlı etkilerini anlatır. [ST01: state-emotion-decisions] Edindiğin kanıtı ve yaptığın davranışı kaydet. Yararlı yanıt, büyük sorunu hâlâ çözümsüz bırakabilir. Güvenle yapabileceğin bir şey yoksa o kısıtı kaydet veya destek seç. Düşünerek verdiğin arayı başarısızlık yapma. Yazılmış bir soruyu da ardından gereken davranışın yapıldığına dair kanıt sayma."]}],sourceIds:["state-regulation-meta","state-emotion-decisions"]}},{schemaVersion:2,revision:2,id:"state-5",courseId:"state",locale:"tr",title:"Mesaj canını yaktı. Gerçekleri değiştirme",goal:"Gerçeği, niyet hakkındaki tahmininden ayır. Sonra aynı tekrarlanan durumda açıklama iste veya kendini koru.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"O mesaj canını yaktı. Niyetlerini tahmin etmeden önce sözlere bak. Güvenli bir yanıt seç.",reason:{id:"state-5-reason",label:"Daha güvenli bir yanıt neyi korur, sana neye mal olur?",kind:"text",maxLength:160,optional:!0,suggestions:["Kendime saldırmadan geri bildirimden yararlanmak","Haksız davranışları artık kabul etmemek","Niyet tahmin etmek yerine soru sormak"]},why:{id:"state-5-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-5-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir olay ile onu açıklama biçimin farklıdır. “Mesajda hakaret var” kontrol edebileceğin bir kanıt. “Kariyerimi mahvetmek istiyorlar” ise niyet tahmini. Başka bir açıklama da gerçeklere uymalı. Zararı zararsız gibi anlatmamalı. Daha olumlu geldiği için bir tahmini gerçek sayma. Mesajdaki sözleri olduğu gibi aktar.","Aynı geçiş anında, bir gerçeği ve hâlâ bilmediğin şeyi belirt. Sonra açıklama iste, düzelt, sınır koy veya destek al. Daha hafif duygu sözcükleri kendiliğinden daha doğru değildir. Klasik adlandırma çalışması, sıkıntıyı yeniden isimlendirince rahatlamayı değil, yüzlere verilen beyin yanıtını ölçtü. Olumluluk yerine doğruluğu seç. Öfkenin adını değiştirmek, bir hakareti ortadan kaldırmaz."],example:{title:"Nazan hakaret içeren mesajları saklıyor",text:"Saat 16.00. Nazan ekipten yine hakaret içeren bir mesaj alıyor. Kimsenin olmadığı bir yerde oturup sakladığı sözleri, gönderenin niyeti hakkındaki tahmininden ayırıyor. Öfkesi sürüyor. Buna yanlış anlaşılma demek yerine güvendiği yöneticiye güvenli bildirim yolunu soruyor. Yöneticinin kontrol etmek için zamana ihtiyacı var. Nazan isteğini kaydediyor, mesajları güvenli biçimde saklıyor."}},move:{invitation:"Bir gerçeğe dayanarak mevcut davranışını geliştir. Belirsizliği netleştir veya zarar belgelenmişse korunmayı seç.",instructions:["Gözleyebildiğin gerçeklerle niyet tahminlerini birbirinden ayır.","Duruma göre açıklama iste, düzeltme yap, sınır koy veya destek iste."],prompts:[],suggestions:{action:["Güvenli bir destek yolunu sor","Gerçek durumu açıklayan tek bir mesaj gönder","İşimde doğrulanmış tek bir hatayı düzelt"],minimum:["Tek bir ihtiyaç için destek iste","Gerçek durum hakkında tek bir soru sor","İşimdeki tek bir hatayı düzelt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Canımı sıkan mesajı kontrol ettikten sonra","Sıradaki planlı yanıtımı vermeden önce"],place:["Güvenli, yalnız kalabildiğim bir koltukta","Güvendiğim bir destek kanalında"],minutes:[2,1,5],fallback:["Kanıtı koru, daha güvenli destek ara","Başka bir güvenli yanıt fırsatı seç"],observation:["Dayandığım gerçek ve verdiğim yanıt","Yorumumu değiştiren kanıtın ne olduğu"]},suggested:{action:"Güvenli bir destek yolunu sor",minimum:"Tek bir ihtiyaç için destek iste",minutes:2,cueHint:"Canımı sıkan mesajı kontrol ettikten sonra",placeHint:"Güvenli, yalnız kalabildiğim bir koltukta",obstacleHint:"Olumlu açıklama, gerçek zararı gizleyebilir.",fallbackHint:"Kanıtı koru, daha güvenli destek ara",observationHint:"Dayandığım gerçek ve verdiğim yanıt"},stopRule:"İstismarı veya tehlikeyi yanlış anlaşılma diye yorumlama. Korunmayı ve destek almayı seç.",accessibleAlternative:"Gerçekleri içinden belirt, yaz, işaret dili kullan veya yardım iste. Bedene odaklanmak veya daha hafif adlandırmak gerekmez."},result:{question:"Seçtiğin, gerçeklere dayanan yanıtı gerçekten verdin mi?",observationPrompt:"Hangi kanıta dayandın, ardından nasıl bir yanıt verdin?"},judgment:{primary:{id:"state-5-documented-insults",scenario:"Nazan tekrar eden hakaretleri içeren mesajları güvenle sakladı. Güvendiği yönetici şimdi ulaşılabilir. Bildirim portalı yarın açılıyor. Acil tehlike yok. Gönderenin niyeti bilinmiyor.",question:"Hangi sonraki adım, gerçekleri ve elindeki desteği kullanır?",bestOptionId:"facts-and-support",options:[{id:"copy-and-wait",text:"Sakladığı hakaret mesajlarının korumalı bir kopyasını daha oluştursun. Sonra bildirim portalının yarın açılmasını bekleyerek o kanalı kullansın.",feedback:"Kanıtı korumak korunmaya hizmet eder. Ama mesajlar zaten güvence altında. Başka kopya, belirlenmiş yeni bir koruma sağlamıyor. Ulaşılabilir yönetici, gönderenle iletişimi gerektirmeden şimdi güvenli bir yolu netleştirebilir."},{id:"facts-and-support",text:"Belgelenmiş hakaretleri, niyet tahminlerinden ayırsın. Sonra güvendiği bir kişiye başvurup destek alabileceği güvenli bir yol sorsun.",feedback:"Bu seçim niyetin belirsizliğini korurken gerçek zararı tanıyor. Nazan gizli niyeti kanıtlamadan, duygusunun adını değiştirmeden veya gönderenle doğrudan yüzleşmeden korunma isteyebilir. Yardım istemek için bunları tamamlaması gerekmez."},{id:"wait-safe-portal",text:"Gönderene ulaşmasın. Yarınki bildirim portalını beklesin. Sakladığı mesajları kullanarak o kanaldan nasıl destek alabileceği hakkında soru sorsun.",feedback:"Doğrudan iletişimden kaçınmak ve bildirim kanalı kullanmak koruyabilir. Burada güvenilir destek daha erken ulaşılabilir. Yolu şimdi sormak, seçeneklerini korur. Bildirimde bulunmaya veya yüzleşmeye zorlamaz. Sonraki kararı yine kendisi verebilir."}]}},carry:{takeaway:"Yorumunu yalnızca kanıtın izin verdiği kadar değiştir. Sonra duruma uygun davranışı seçip yap.",followUp:{questionId:"state-5-return",question:"Yorumunu hangi kanıt destekledi, hangisi ona uymadı? Verdiğin yanıt bu kanıta uydu mu?",observationPrompt:"İlgili gerçeği, kalan belirsizliği ve verdiğin yanıtın kanıta uyup uymadığını belirt.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Beyinde ölçülen fark, sıkıntı tedavisi değildir",paragraphs:["Lieberman ve arkadaşları, beyin görüntüleme sırasında yüzlerdeki duyguları adlandıran 30 sağlıklı yetişkini inceledi. Duygu sözcüğü koşulu ile cinsiyete uygun isim koşulu, amigdalada ölçülen bir değerde farklıydı. Çalışma, “çok öfkeliyim” yerine “sinirlendim” demenin günlük sıkıntıyı azalttığını göstermedi. Kendi duygunu adlandırmanın aynı etkiyi yarattığını veya yararın sürdüğünü de göstermedi. [ST11: state-affect-labeling] Bunlar farklı uygulamalar ve sonuçlardır.","Bu derste ODA, gerçeğe, duyguya ve belirsizliğe bakmanı ister. Amaç, sıradaki seçimini açıkça görmen. Yaşadığın güçlü duygunun adını doğru koyabilir, hiç adlandırmayabilir veya notu kendine saklayabilirsin. Sonradan daha az öfkeli hissetsen de belgelenmiş hakaret yine hakarettir. Şu an çok kaygılı olsan da geciken kısa bir yanıt belirsiz kalabilir. Mesajın tam sözlerini kullanabilirsin. Kontrol edilebilene dayan, bilinmeyeni koru. Güvenliğine ve istediğin yola uyan davranışı seç. Bir başkasının niyetini yalnızca duygundan çıkaramazsın. Duyguyla gerçeği aynı ölçü gibi kullanma."]},{heading:"Yeniden değerlendirmek sınır koymayı da içerebilir",paragraphs:["Bir yorumu değiştirmek, çoğu zaman yeniden değerlendirme diye adlandırılır. Webb ve arkadaşları farklı deneysel karşılaştırmalarda ortalama yararlar buldu. Yöntemler ve sonuçlar arasında açık farklar vardı. Bu, olumlu açıklamayı her zaman en iyi yapmaz. Kanıt, tam bu bir dakikalık çalışmayı doğrulamıyor. Geri bildirimi, kaynak kısıtlarını veya zararı görmezden gelmeyi haklı da çıkarmıyor. [ST02: state-regulation-meta]","Adil bir yorum sorumluluğu belirginleştirebilir: işin bu kısmını atladım, onu düzelteceğim. Dayanaksız suçlamayı da azaltabilir: yanıt neden gecikti bilmiyorum, soracağım. Zarar belgelenmişse korunmayı destekleyebilir: yardım istemeden önce niyeti kanıtlamam gerekmiyor. Hangi davranışın yapıldığını, hangi yeni kanıtın çıktığını kaydederek aynı denemeyi sürdür. Yanıtsız istek, yanıtsız kalır. Güvenliğin için durduysan kaydında da durduğunu belirt. Kaydın kabul edilebilir olması için ikisini de daha iyimser bir hikâyeye dönüştürmen gerekmez. Olanı olduğu gibi anlatabilirsin."]}],sourceIds:["state-affect-labeling","state-regulation-meta"]}},{schemaVersion:2,revision:2,id:"state-6",courseId:"state",locale:"tr",title:"Olumlu sözler sahte mi geliyor? Somut adım at",goal:"Minnettarlığı veya ruh hâli değişimini şart koşmadan mevcut işine başlamak için inanabileceğin bir davranış cümlesi kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Sabah hazırlığın tamam. Peki ardından gerçekten bir adım attın mı?",reason:{id:"state-6-reason",label:"Bu hazırlığı uzattıkça hangi iş hâlâ sonraya kalıyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Seçtiğim davranışı yapmaya başlamak","İnanabileceğim sözlerle kendime yol göstermek","Hazırlığı kısa tutup işi denemek"]},why:{id:"state-6-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-6-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Büyük olumlu sözlerin herkesin ruh hâlini iyileştirdiği kanıtlanmış değil. İlk çalışmalardaki yarar ve ters etki bulguları, sonraki tekrar çalışmalarında elde edilemedi. Güçlü söyleyişin veya coşkulu telkinlerin bunu çözdüğüne dair burada doğrulanmış kanıt yok. Yapabileceğin bir işi anlatan sade bir yönerge seç. Söylediğini kusursuz biçimde hissedene kadar beklemen gerekmiyor.","Aynı geçiş anında “Emin değilken de açık bir istek gönderebilirim” de. Sonra uygunsa gönder. İstersen minnettarlık için gerçek bir şeyi an. Hayal edilen başarıyı değil. Zoraki geliyorsa atla. Cümle hazırlıktır. Davranışı ayrı kaydet. Kendini ikna olmuş hissetmek veya bütün ritüeli tamamlamak gerekmez. Yapılan işin ne olduğu açık kalsın."],example:{title:"Ayşe ilk isteğini iletiyor",text:"Saat 08.00. Ayşe sabah çayını bitirmiş. Çıkmasına iki dakika var. “Beni hiçbir şey durduramaz” sözü sahte geliyor. “Emin değilken de açık bir soru sorabilirim” diyor. Ertelediği isteği gönderiyor. Bugün minnettarlık kısmını atlıyor. Çıkmadan önce yanıt gelmiyor. Belirsizliği başarısızlık saymadan gönderdiği cümleyi kaydediyor. İstek gönderildi, yanıt hâlâ bekliyor."}},move:{invitation:"Hazırlığı kısa tut. İnanabileceğin tek bir cümle kullan. Sonra mevcut yararlı davranışını yap.",instructions:["Kendi yapabileceğin bir davranış hakkında cümle seç.","Uygunsa şimdi dene. Değilse gerçekten başlayacağın anı kaydet."],prompts:[],suggestions:{action:["Seçtiğim açık isteği karşı tarafa gönder","İşim için kullanılabilir tek bir cümle yaz","Somut bir ihtiyaç için destek iste"],minimum:["Tek bir açık cümle gönder","İşe yarayan tek bir cümle yaz","Destek gereken tek bir ihtiyacımı belirt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Sabah çayımı bitirdikten sonra","İşime geçmek için zaten seçtiğim anda"],place:["Mutfak masamın başında otururken","Genellikle kullandığım çalışma yerinde"],minutes:[2,1,5],fallback:["Ritüeli atla, seçtiğim cümleyi kullan","Bir sonraki gerçekçi fırsatı seç"],observation:["Sözlerimin davranışa götürüp götürmediği","Hangi hazırlığın davranışımı geciktirdiği"]},suggested:{action:"Seçtiğim açık isteği karşı tarafa gönder",minimum:"Tek bir açık cümle gönder",minutes:2,cueHint:"Sabah çayımı bitirdikten sonra",placeHint:"Mutfak masamın başında otururken",obstacleHint:"Hazırlığı tekrar tekrar uzatıyorum.",fallbackHint:"Ritüeli atla, seçtiğim cümleyi kullan",observationHint:"Sözlerimin davranışa götürüp götürmediği"},stopRule:"Sıkıntını artıran minnettarlığı, canlandırmayı veya cümleleri atla. Yerine gündelik destek seç.",accessibleAlternative:"Normal nefes al. Gözlerin açıkken çevrene dikkat et. Yönergeyi söyle, yaz, işaret diliyle veya içinden kullan."},result:{question:"Cümlenden sonra seçtiğin davranışı gerçekten yaptın mı?",observationPrompt:"Gerçekte neye başladın, ne gönderdin veya neyi değiştirdin?"},judgment:{primary:{id:"state-6-believable-start",scenario:"Ayşe’nin çıkmasına iki dakika var. Kontrol ettiği sorusu açık, nazik ve güvenli bir kanaldan gönderilmeye hazır. Kendinden emin görünmek istediği için tekrar tekrar erteliyor.",question:"Bu sabaha hangi seçenek daha iyi uyar?",bestOptionId:"credible-and-send",options:[{id:"rehearse-and-send",text:"Doksan saniye mesajı sesli söyleyerek prova yapsın. Sonra kontrol etmiş olduğu soruyu evden çıkmadan önce göndersin.",feedback:"Süreli prova, belirsiz veya tanımadığın bir isteğe yardımcı olabilir. Bu soru zaten açık ve kontrol edilmiş. Prova, önce kendinden emin olmak gerektiği inancına yanıt vermeden fırsatın çoğunu tüketiyor."},{id:"credible-and-send",text:"Emin değilken soru sormaya dair inanabileceği bir yönerge kullansın. Ardından hazır olan soruyu güvenli kanaldan göndersin.",feedback:"Bu seçim, uygulayabileceği bir yönergeyi hemen yapabileceği bir işle birleştiriyor. Ayşe yararlı isteğini iletmeden önce büyük bir iddiaya inanmak, minnettarlık hissetmek veya belirsizliğini yok etmek zorunda değil."},{id:"polish-and-send",text:"Mesaj için kısa bir giriş ve kapanış taslağı yazsın. Sonra hazır sorusunu evden çıkmadan önce göndersin.",feedback:"Giriş ve kapanış gerektiğinde nezaket katabilir. Hazır soru isteği zaten iletiyor. Daha fazla düzeltmek, göndermek için daha az zaman bırakır. İnanabileceği yönerge, emin değilken başlamayı doğrudan ele alır."}]}},carry:{takeaway:"Sözlerin kullanabileceğin kadar inandırıcı olsun. Kanıt olarak ardından gerçekten yaptığın davranışı göster.",followUp:{questionId:"state-6-return",question:"Cümle adım atmana yardımcı mı oldu, geciktirdi mi, yoksa belirgin fark yaratmadı mı?",observationPrompt:"Yardımı veya gecikmeyi davranışın sonucundan ayrı anlat. Belirgin fark olmaması da geçerli.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Olumlamalara dair kanıtlar karışık",paragraphs:["Wood ve arkadaşları üniversite örneklemlerinde, olumlu kişisel cümlelerin tekrarlanmasını inceledi. İlk bulgular öz saygıya göre farklı yanıtlar olabileceğini gösterdi. Bazı katılanlarda daha kötü yanıt da vardı. Flynn ve Bordieri’nin sonraki iki tekrar denemesi; ruh hâli, o anki öz saygı veya etkiyi değiştiren koşullara dair bulguları yeniden elde etmedi. Doğru sınır, karışık kanıttır. Olumlamaların herkese yaradığı veya herkese zarar verdiği iddiası değil. [ST12: state-positive-self-statements; ST20: state-affirmation-replication]","Bu kanıt, bedeni de kullanarak yapılan coşkulu telkinleri çözüm olarak belirlemiyor. Tek bir davranış hakkında inanabileceğin bir yönergeyi burada pratik koçluk olarak sunuyoruz. Kanıtlanmış psikolojik tedavi olarak değil. Kendi sözlerini kullanabilir, cümleyi atlayabilir veya destek seçebilirsin. İş ve en küçük adım, gözleyebileceğin kadar açık kalsın. Gelecekte yapacağın iş hakkında cümle söylemek hazırlıktır. İsteği göndermek, işteki hatayı düzeltmek veya destek istemek ise sonra bildirebileceğin davranıştır."]},{heading:"Minnettarlığın sınırları var, zorunluluğu yok",paragraphs:["Kirca ve arkadaşları, ifade edilen şükran üzerine 25 rastgele atanmış örneklem içeren 23 çalışmayı inceledi. Nötr kontrol koşullarına göre olumlu iyi oluşta küçük bir ortalama yarar bulundu: etki 0,22. İyi oluşu desteklemeyi amaçlayan başka etkinliklere göre tahmin daha küçüktü ve istatistiksel sonuç kesin değildi. [ST13: state-gratitude-expressed] Görülen yararı değerlendirirken karşılaştırılan etkinliğin ne olduğu önem taşıyor.","Bu araştırma on dakikalık hazırlık paketini, gelecekteki üç sahneyi hayal etmeyi, en iyi sabah sırasını veya uygun klinik tedaviye üstünlüğü belirlemiyor. Minnettarlığı seçersen sana iyi gelen gerçek bir ayrıntıyı kullan. Kayıptan güzel bir yan çıkarmayı veya güvenli olmayan birine şükran duymayı şart koşma. Umduğun gelecek bir olasılık. Anı veya başarılmış sonuç değil. Sürdürdüğün denemede pratik soru şu: isteğe bağlı hazırlık aynı yararlı davranışı destekledi mi? Gecikme veya rahatsızlık ekliyorsa bırak."]}],sourceIds:["state-positive-self-statements","state-affirmation-replication","state-gratitude-expressed"]}},{schemaVersion:2,revision:2,id:"state-7",courseId:"state",locale:"tr",title:"Hazırlık biriktirme. Gelecek hafta işe yarayanı seç",goal:"Gerçek kayıtlarına bakarak aynı denemeyi gelecek hafta korumayı, küçültmeyi, değiştirmeyi veya ara vermeyi seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hazırlık uzuyor, iş hâlâ bekliyor. Hangi kısmı başlamana yardımcı oldu, hangisi gecikme ekledi?",reason:{id:"state-7-reason",label:"Bu denemeyi sürdürürsen gelecek hafta hangi işe daha az yer kalır?",kind:"text",maxLength:160,optional:!0,suggestions:["Sıradaki yararlı adımımı korumak","Gereken dinlenme ve toparlanmayı korumak","Beni geciktiren ritüeli bırakmak"]},why:{id:"state-7-why",label:"Bu adım, bu hafta neye yer açmanı sağlar?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"state-7-cost",label:"Şu anki davranışın sana neye mal oluyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İstenen gelecek için engel ve yanıt planının, kötü sonuçları gözünde canlandırmaya göre daha doğrudan araştırma desteği var. Gözünde canlandırdığın kötü sonuçlar birer tahmindir. Yaşanmış olaylar değildir. Utanç veya daha güçlü sözler gerekmez. Plan yapmak için kendini kötü hissetmeni şart koşma.","Aynı geçiş anındaki gerçek kayıtlarına bak. Hangi hazırlık yararlı davranışını destekledi? Hangisi rahatsızlık, gecikme veya belirgin fark olmamasıyla sonuçlandı? İşe yarayan tek bir biçimi koru, tek bir sorunu değiştir veya ara ver. Gelecek haftanın en küçük adımı gücüne uysun. Mümkünse uygun bir adım dene. Dinlenmek, korunmak ve destek de plana dahil olabilir."],example:{title:"Emre daha küçük bir hedef seçiyor",text:"Pazar öğleden sonra Emre masasında, portfolyosuna başlama kayıtlarını inceliyor. Dikkatini çevresine verdiği bir ara başlamasına yardım etti. Uzun ritüel ise iki kez geciktirdi. Bugün kötü uyuduğu için ritüeli atlayıp tek bir görsel açıklamasını düzeltiyor. Salı için aynı küçük adımı planlıyor. Portfolyo bitmedi. Ama yeni planı artık gördüklerine uyuyor."}},move:{invitation:"Aynı denemenin kayıtlarını kullan. İşe yarayan tek bir biçimi koru, yapabileceğin en küçük adımı dene.",instructions:["Bildirdiğin denemeleri gözden geçir. Sonucu yazılmamış olanlar bilinmeyen kalsın.","Gelecek hafta için tek bir biçimi koru, küçült, değiştir veya ara ver."],prompts:[],suggestions:{action:["İşimdeki yararlı adımı yeniden yap","Sıradaki açık isteğimi dile getir","Seçtiğim toparlanma adımını uygula"],minimum:["İşimdeki tek bir hatayı düzelt","İsteğimi anlatan tek bir cümle kullan","Seçtiğim süreyi dinlenip toparlanmaya ayır"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Daha önce deneyip yararlı bulduğum geçiş anında","Bir sonraki gerçekçi fırsatım geldiğinde"],place:["Genellikle kullandığım çalışma yerinde","Toparlanmak için seçtiğim yerde"],minutes:[2,1,5],fallback:["Adımı bugünkü gücüme uydurmak için küçült","Ara ver, destek için bir adım seç"],observation:["Tekrarladığım veya değiştirdiğim şey","Gerçekte karşıma çıkan engelin ne olduğu"]},suggested:{action:"İşimdeki yararlı adımı yeniden yap",minimum:"İşimdeki tek bir hatayı düzelt",minutes:2,cueHint:"Daha önce deneyip yararlı bulduğum geçiş anında",placeHint:"Genellikle kullandığım çalışma yerinde",obstacleHint:"Her zamanki planım gücümün yettiğinden daha fazlasını istiyor.",fallbackHint:"Adımı bugünkü gücüme uydurmak için küçült",observationHint:"Tekrarladığım veya değiştirdiğim şey"},stopRule:"Sıkıntı veren kötü sonuçları gözünde canlandırmayı atla. Dinlenmek, korunmak ve destek almak uygun sonraki adımlar olabilir.",accessibleAlternative:"İçinden veya yardımla değerlendir. Ara yardımcı olacaksa gözlerin açık, oturarak ve hareket etmeden ilerleyebilirsin."},result:{question:"Sıradaki deneme için seçtiğin en küçük adımı yaptın mı?",observationPrompt:"Neyi korudun, değiştirdin veya durdurdun? Gerçekte ne oldu?"},judgment:{primary:{id:"state-7-capacity-review",scenario:"Emre kötü uyuduktan sonra kullanabileceği beş dakikaya sahip. Görsel açıklamasında bilinen bir hata var, düzeltmesi hazır. Teslim haftaya. Uzun hazırlık son iki başlangıcını geciktirdi.",question:"Hangi sonraki plan gördüklerine daha iyi uyar?",bestOptionId:"small-caption",options:[{id:"small-caption",text:"Bir portfolyo görselinin açıklamasını düzeltsin. Küçültülmüş denemeyi kaydetsin. Gücüne göre bir sonraki gerçekçi çalışma zamanını seçsin.",feedback:"Bu seçim amacı korurken bugüne uyması için miktarı değiştiriyor. Emre kayıtlarından yararlanıp başka fırsat planlayabilir. Uzun ritüel veya kusursuz enerji şartı koyması gerekmiyor. Küçük işi bugün yapabilir."},{id:"sort-next-section",text:"Beş dakikayı sıradaki bölümün kaynak notlarını sıralamak için kullansın. Bilinen görsel açıklaması düzeltmesini salı yapmaya bıraksın.",feedback:"Notları sıralamak sonraki bölüme hazırlık olabilir. Ama hazırlık, yararlı işi tekrar tekrar geciktirdi. Mevcut düzeltme hazır. Bu küçük kısmı tamamlamak, kayıtta görünen engeli ele alan bir planı sınar."},{id:"defer-for-checking",text:"Görsel açıklamasını düzeltmeyi yarın dinlenmiş olacağı zamana bıraksın. Bu beş dakikayı, kontrol için bir çalışma zamanı ayırmaya kullansın.",feedback:"Yorgunluk işi uygunsuz kılıyorsa veya doğruluk kontrolü gerekiyorsa ertelemek uygundur. Burada düzeltme hazır, kullanabileceği güce de uyuyor. Başka kontrol planlamak, şimdi yapabileceği anlamlı bir kısmı sonraya bırakıyor."}]}},carry:{takeaway:"Amacını koru. Sıradaki planını, gerçek denemelerine ve bugün elindeki güce bakarak şekillendir.",followUp:{questionId:"state-7-return",question:"Sıradaki planın gücüne uydu mu? Gerçekte hangi engel onu etkiledi?",observationPrompt:"Neyin uyduğunu, önüne ne çıktığını veya toparlanmanın ya da başka değişikliğin neden uygun olduğunu anlat.",adjustmentPrompt:"Sıradaki denemenin hayatına daha iyi uyması için ne gerekiyor?"}},goDeeper:{sections:[{heading:"Engel planının kanıtı var. Felaket sahnelerini atlayabilirsin",paragraphs:["Wang ve arkadaşları, 15.907 kişinin katıldığı 21 makaleden 24 bağımsız etkiyi birleştirdi. Zihinsel karşılaştırmayla yanıt planlamanın, hedefe ulaşmada küçük ile orta arasında ortalama etkisi 0,336’ydı. Yayın yanlılığına göre düzeltilmiş tahmin daha küçüktü. Araştırma sonuçları farklılık gösteriyordu. Yöntem, ulaşılabilir bir gelecek isteğini, önündeki engeli ve “bu engel çıkarsa şunu yaparım” planını birleştirir. Dickens yöntemini, utanç yaratmayı veya her “yapmalıyım”ı “mecburum”a çevirmeyi doğrulamaz. [ST15: state-mental-contrasting]","Kayıtlarının veya koşullarının desteklediği bir engel kullan. İçinde yaşadığın bir tepkiyse yapabileceğin bir yanıt belirt. Dışarıdaki bir engelse kaynak, başka ortam veya yardım gerekebilir. Gözünde canlandırdığın gelecekteki kötü sonuçlar, tahmin olarak kalır. Bu planın geçerli olması için acı anıları yeniden yaşamak veya giderek büyüyen zararı gözünde canlandırmak gerekmez. Buradaki daha kısa, kayda dayalı yaklaşım ODA uyarlamasıdır. Süresi bir tahmindir. Doğrulanmış en iyi süre değildir."]},{heading:"Yeni ritüel eklemek yerine denemeni toparla",paragraphs:["Kurs tek bir geçiş anı ve yararlı davranışla başladı. Gelecek haftaya neyi taşımaya değer bulduğuna karar vermeden önce tam o denemelere bak. Denenmiş hazırlığı tamamlanmış işten ayır. Değişmemiş duyguyu, yapılmamış en küçük adımla aynı sayma. Eksik bildirim hiçbir sonuç vermez. Koşula bağlı fırsat hiç gelmediyse fırsat olmadığını kaydedebilirsin. Her sonraki seçimin, bilinen gerçeğe yanıt versin.","Breines ve Chen, kısa deneylerde kendine şefkatin gelişme isteğiyle birlikte bulunabileceğini gösterdi. Başarısız sınavdan sonra şefkat grubu, hatırlatma almayan koşuldan daha uzun çalıştı. İkinci sınav performansında istatistiksel olarak anlamlı fark bulunmadı. Öz saygı karşılaştırması da kesin sonuç vermedi. [ST16: state-self-compassion-motivation] Bu, çaba için kendini aşağılamanın gerekli olduğu varsayımını bırakmayı destekler. Davranış değişiminin sürmesini garanti etmez. Sıradaki planın destek almayı, toparlanmayı veya koşullarına uymayan planı bırakmayı içerebilir. Kayıt ve tarihli değerlendirme, kesintisiz gün sayısını zorunlu tutmadan bu kararları dürüst tutar."]}],sourceIds:["state-mental-contrasting","state-self-compassion-motivation"]}}],k=[{id:"state-1",schemaVersion:2,practice:["Duygunun nerede başlamış olabileceğini söyle.","Tamir için tek bir açık istek gönder","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:2,photo:{id:"1758192139097-1e7f30c2498e",alt:"Güneş ışığı alan ağaçların altında sakin şehir sokağından karşıya geçen adam"}},{id:"state-2",schemaVersion:2,practice:["Tek bir araç seç veya her zamanki hareketsiz hazırlığını koru.","İşim için kullanılabilir tek bir cümle yaz","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:1,photo:{id:"1692933216024-8de20c41321a",alt:"Yeşil bitkilerin arasındaki ahşap yürüyüş yolunda ilerleyen kadın"}},{id:"state-3",schemaVersion:2,practice:["Otur. Araç kullanma, sudan ve düşme riski olan yerlerden uzak dur.","Düşünerek seçtiğim tek yanıt cümlesini gönder","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:0,photo:{id:"1763713383838-5cd702c13160",alt:"Ormanda gözleri kapalı, kendine nazikçe sarılan kadın"}},{id:"state-4",schemaVersion:2,practice:["Gerektiğinde araştırmayı sürdür ve kimin sorumlu olduğunu açık tut.","Gereken bir ayrıntı için açıklama iste","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:2,photo:{id:"1543379232-77ee894c85dd",alt:"Örgü bere takmış, alçalan güneşe doğru bakan kadın"}},{id:"state-5",schemaVersion:2,practice:["Gözleyebildiğin gerçeklerle niyet tahminlerini birbirinden ayır.","Güvenli bir destek yolunu sor","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:1,photo:{id:"1534330207526-8e81f10ec6fc",alt:"Aydınlık bir pencerenin önünde sessizce duran adam"}},{id:"state-6",schemaVersion:2,practice:["Kendi yapabileceğin bir davranış hakkında cümle seç.","Seçtiğim açık isteği karşı tarafa gönder","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:1,photo:{id:"1552838671-0e948f9f69b5",alt:"Yeşil çimende oturup sabah güneşine bakan kadın"}},{id:"state-7",schemaVersion:2,practice:["Bildirdiğin denemeleri gözden geçir. Sonucu yazılmamış olanlar bilinmeyen kalsın.","İşimdeki yararlı adımı yeniden yap","Gerçekte ne olduğunu kaydet. Sıradaki uygun denemeyi seç."],correct:0,photo:{id:"1633210155534-e43f00c1d627",alt:"Doğada bir kayanın üstüne oturup defterine yazan kadın"}}],m={id:"state",title:"Hâlâ gergin misin? Sıradaki adımını seç",subtitle:"7 ders. İşe yarayan bir davranışı dene. Öncesinde yardımcı olabilecek araçları istersen kullan.",description:"Gündelik bir geçiş anı seç. Rahat bir hazırlık yap, durumu doğru yorumla, adım at ve olanı değerlendir. Daha iyi hissetmeyi şart koşmadan hayatına katkısı olanı koru.",scope:"Ruh hâlini ve enerjisini gündelik araçlarla değiştirmek isteyen yetişkinler için eğitimdir. Tanı veya tedavi değildir. Kaygı bozuklukları, panik bozukluğu veya depresyon tedavisi değildir. Terapinin veya ilacın yerini tutmaz. Nefes alıştırmasında başın dönerse, sersemlemiş hissedersen, karıncalanma veya nefes darlığı olursa hemen dur. Normal nefesine dön ve otur. Kalp veya akciğer hastalığın varsa ya da hamileysen enerji artırmayı amaçlayan nefes çalışmasını denemeden önce bir sağlık uzmanına danış. Araç kullanırken veya su içindeyken asla yapma. Kriz yaşıyorsan veya kendine zarar verme düşüncelerin varsa yerel acil yardım numarasını ara: Türkiye’de ve Avrupa’nın büyük bölümünde 112, ABD’de 911.",outcome:"Tekrarlanan bir geçiş anında yararlı bir davranış, dürüst deneme kayıtları ve gücüne uyan gelecek hafta planı.",photo:{id:"1500080628126-901233e80205",alt:"Akşamın altın ışığında ahşap iskelede bir elini ışığa doğru kaldıran kadın"},lang:"tr",lessons:d.map((a,t)=>{const r=k[t],e=a.judgment.primary,n=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==n.id).map(i=>i.text);return l.splice(r.correct,0,n.text),{...r,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l,feedback:n.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})};export{m as COURSE,d as LESSONS_V2,s as SOURCES};
